import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易经传集解卷四","description":"周易经传集解 - 周易经传集解卷四","frontmatter":{"title":"周易经传集解卷四","description":"周易经传集解 - 周易经传集解卷四"},"headers":[],"relativePath":"zh/classics/jingchuan-jijie/005.md","filePath":"zh/classics/jingchuan-jijie/005.md"}'),r={name:"zh/classics/jingchuan-jijie/005.md"};function c(o,a,l,d,p,h){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易经传集解卷四",tabindex:"-1"},[n("周易经传集解卷四 "),e("a",{class:"header-anchor",href:"#周易经传集解卷四","aria-label":"Permalink to “周易经传集解卷四”"},"​")],-1),e("p",null,"钦定四库全书周易经传集解师比卷四 ​宋林栗撰序卦曰：「讼必有众起，故受以师。」师者，众也。「师」，讼之变也。自讼而师，下坎不动，上乾变坤而成卦也。乾自需而讼，至于上九，反入于渊，是以变而为坤。夫民有所不得其平，而后至于讼。讼而有以正之，则始乎讼而卒于无讼，是之谓治世。及其乱也，以讼济讼，相激为深而己。有冤而无所诉，有诉而无所直，疾视其长上而幸其危亡，其不起而为乱者，未之有也。是以秦之将亡，其民皆欲剚刃于其长吏，而后干戈之事兴矣。故曰：「讼必有众起，故受之以师。」师者，众也。坤三为众，又合坎之二阴，斯为大众矣。而坎中一阳实居下卦之中，五阴虽众，莫能相摄，其势必归于一阳。一阳在下而为众阴之主，非行师之义而何以当之哉？是以谓之师也。师：贞，大人吉，无咎。彖曰：「师」，众也；「贞」，正也。能以众正，可以王矣。刚中而应，行险而顺，以此毒而天下，而民从之，吉又何咎矣？上坤下坎成卦曰「师」者，坎为险，震为动，坤为众，为顺。以险动众，师旅之事也；以顺行险，师旅之义也。夫兵，凶器也；战，危事也。圣人岂得已而用之哉？将以诛除暴乱，保卫生灵，顺天之心，因民之欲，兴动大众，而人不以为劳；驱之于万死一生之地，而人不以为怨，凡以其顺动之故也。然十人之聚，必听其雄；百夫之群，必建其长。聚大众而无以正之，未见敌而先自败矣。故曰：「师贞。」贞，正也，政令之所自出也。五阴而一阳，则一阳为之正也。一阳而于五阴之正，号令赏罚，莫敢不从。位宜在上，而反居于下，何也？师，帅之义也。有君在上，而帅得专之，虽君命有所不受，应其义矣。古者诸侯或七十里，或五十里，大者不过百里，行军用师，未尝不躬亲之。惟王者之师，则命将统之，王不亲行也。故曰：「大人吉。」大人，谓五也。子曰：「师，众也。贞，正也。能以众正，可以王矣。」传曰：「师能左右之曰以。」众之所奉以为正，而我能以之，不曰「大人」乎？古易诸家皆作「大」，自王弼以来本多作「丈夫」之「丈」。九二有正众之才，而屈下为其君。六五以天下之众，而委听于其臣。杀伐果敢，而上无猜疑之端；威权假人，而下无骄恣之渐，夫何往而不济？故曰「吉」，又曰「无咎」。子曰：「刚中而应，行险而顺，以此毒天下而民从之，吉又何咎矣？」刚而得中，志应于上，二之所以「吉无咎」也。行天下之险，而顺天下之心，五之所以「吉无咎」也。二爻之辞俱言之矣。或曰：震居坎中，故曰「行险」，而以六五当之，何也？曰：「师」之二五，相应者也。二之行险，五之命也。金石草木，莫不有毒，平居畏忌，无所不至，而疾病用之。兵之除害，犹治疾也。聚天下不义之徒，授之以不仁之器，而教之以杀人之事，以至仁伐至不仁，犹有血流漂杵之祸，夫是故谓之「毒」。以毒被天下，宜其怨苦，然而民乐从之者，顺其心而除其害也。应天顺人，吉又何咎哉？象曰：地中有水，「师」，君子以容民畜众。「地」者，「坤」也；「水」者，「坎」也。地无所不容，水无乎不在，故「君子以容民畜众」象之。「地中有水」，水之聚也。三军六师，民之聚也。君子之聚民，如地中之畜水，则无流散奔冲之患矣。卦言师众，本取诸「坤」，而大象则取诸「坎」，其归一也。杂卦曰：「师，忧也。」「坎」之一阳为五阴之主，故有忧象，「坎」为忧故也。是故「师」之六爻，皆取忧惧之义焉。忧之如何？兴天下之众，而行天下之险，是其所以忧也；居人臣之位，而有天下之权，是其所以忧也。夫九二者，「师」之主也。二在忧惧之中，而诸爻欲无忧惧，得乎哉？是故初六有「失律」之忧，六三有「无功」之忧，六四有「失常」之忧，六五有「不当」之忧，上六有「乱邦」之忧。至于诸爻言「吉」，必曰「无咎」，其忧之也至矣。初六：师出以律，否臧，凶。象曰：「师出以律」，失律凶也。初六，坎也，以阴居刚，而在一卦之下，上无其应，而承于九二之震，故曰：「师出以律，否臧凶。」坎为律，震为出。古者出师，授之同律，所以整军而经武也。在师之初，有出师以律之象。然以六居之，未必能持律也。四阴皆体「坤」居前而顺九二之命，见危临难，有不敢避。独初六体「坎」而居其后，故有「否臧」之凶。「臧」言「律」也，「否」言失也。出师之初而失其律，「凶」可知也。或曰：以「律」训「臧」，未闻前诂。曰：「臧」之言善也，善持律之谓也。得律为臧，失律为否，复何疑乎？师之初六，后军之象也。后军不整，师之通患也。使初而非阴，则师之象毁矣。及其为阴也，又有「失律」之忧。故圣人两著其辞，以明得失之未可知，而忧惧之不敢忘也。子曰：「师出以律，失律凶也。」「否臧」之义，明白如此，而古今诸儒不胜异说，惟左氏传为得之。曰：执事顺成为臧，逆为否。否，逋靡反。或曰：「诸儒言律，或以为律法之律，或以为吹律之律，二者将安折中？」曰：「法律本于吹律，律起于黄钟。黄钟，坎也。古者断竹为律，吹中声以验气候，轻重长短，毫厘不差，度量权衡，于此而取则焉。是以后世法令通谓之律，取其无差忒也。」今此言「否臧之凶」，直谓法律尔，非谓吹律以听军声也。若谓吹律以听军声，一乐师之职耳。世无师旷，战胜攻取，固自若也，何以言其「凶」乎？尔雅曰：「坎，律，铨也。」郭璞注曰：「易坎卦主法，法律皆所以铨量轻重。」盖得之矣。九二：在师，中，吉，无咎。王三锡命。象曰：「在师中吉」，承天宠也。「王三锡命」，怀万邦也。九二，震也。以阳居柔，而在下卦之中，应乎六五之「坤」，而为群阴之主，故曰「在师」。师，众也。「坤」为众，为顺；震为长，为动。动而顺，刚中而应，故曰：「中吉，无咎，王三锡命。」一阳居下，而为五阴之主，六五听之，群阴顺之，不在师而在国，则权臣之象矣。在师而不得中，未可以言吉。禀命则不畏，专命则不臣，专禀之贵乎中也。猛则失恩，宽则失威，宽威之贵乎中也。在师而得中，是以「吉」而「无咎」也。象所谓「师正吉无咎」是也。「王」，谓六五也。自五至二，所历三爻，三锡命也。将帅而师，而王之锡命至于再三，所以昭宠渥而重其权也。夫为将者，所有之师，君之民也；所行之赏罚，君之柄也。君与之民，必与之柄。可赏而赏，可罚而罚，可诛而诛，可赦而赦，百万之众，莫敢不从，所恃者君命也。君无锡命，跬步不可行矣。是以古者遣帅推毂，而命之曰：「阃外之事，将军主之。」犹以为未也，而至于再，至于三，斯可以信其恩威，而令其下矣。故曰：「在师中吉，承天宠也。」或曰：六五，坤也，而曰承天宠，何哉？曰：五者，天之位也。自天宠之，吉无咎矣。「王三锡命」，怀万邦也。王之所以三锡命者，岂私于一师哉？所以怀来万邦也。或曰：「宠一师而怀万邦，其义安在？」曰：勤而见知，忠而见信，群臣诸侯莫不劝矣。不庭之方，不率之国，莫不惧矣。好我者莫不劝，恶我者莫不惧，怀来之术，有过于此者乎？六三：师或舆尸，凶。象曰：「师或舆尸」，大无功也。六三上体为「坤」，下体为「坎」，以阴居刚，而在下卦之上，上无其应，而乘乎九二之「震」，故曰：「师或舆尸，凶。」夫六五者，师之王也；九二者，师之帅也。六五体「坤」，「坤」为母；九二体震，震为长男。初六、六三体坎，「坎」为中男；六四体「艮」，艮为少男。以九二刚中之才，有六五柔上之应，凭冢嗣之贵，居师帅之任，「坎」、「艮」诸男，莫不听顺，此其所以「吉」也。然母之于子，亲而不尊，多爱而少威，虽以师帅之权付之长子，至于「艮坎」诸男，未必不使之分其任也，故「或」之。「或」之者，疑也。「舆」者，众也。「尸」者，主也。三、四以「坎」「艮」而杂乎「坤」，「坤」为众，故有「舆尸」之象。行军用师而众主之，则号令不一，人心不齐，甲可乙否，莫知适从，如是而不败者，未之有也。所以然者，初六、六三不当其位，而四比于五，有爱季之嫌故也。子曰：「师或舆尸，大无功也。」师无统一，未战先溃，劳民费财而无尺寸之功，固可以言凶矣。何必前徒倒戈，流血漂杵，然后谓之凶乎？程氏曰：「自古任将不专而致覆败者，晋荀林父邲之战、唐郭子仪相州之役是也。」六四：师左次，无咎。象曰：「左次，无咎」，未失常也。六四上体为「坤」，下体为「艮」，以阴居柔，而在上卦之下，下无其应，而承于六五之「坤」，故曰：「师左次，无咎。」「坤」为顺，「艮」为止，故有「左次」之象。老氏有言：「君子居则贵左，用兵则贵右。」偏将军处左，上将军处右，则左者不用之地，犹人之左手足不如右强也。不用之地，师之次舍也。「坤」为地，「艮」为山，「坎」为水。师之所次，右背山林，前左水泽。六四皆水而次，何也？曰：四之为「艮」，其体反也，故水泽为前左，而山陵平地为右背矣。以阴居刚，体乎「坤艮」，有「舆尸」之象，为其背山左水，有师次之象焉。是以变而言之也，止则如山，动则如雷，师之道也。故子曰：「左次无咎，未失常也。」若以阴居刚，则失其常矣。而「艮」体尸之，得为无咎乎哉？说者谓六四自度非才而不敢进，故得无咎。夫师帅者，社稷之司命，政之存亡，民之死生，于是乎在，可以非才而受其任乎？既受任矣，而「巽」儒不进，谓人曰：「我不能，虽复左次，其能免乎？」六五：田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。象曰：「长子帅师」，以中行也。「弟子舆尸」，使不当也。「言」，当作「吉」，字之误也。今改正。六五，「坤」也。以阴居刚，而在上卦之中，应乎九二之「震」，而乘乎六四。四，「坤」「艮」也，故曰：「田有禽，利执」。「坤」为地，故有田象。「艮」为黔喙之属，故有禽象。「坤」之有「艮」，犹田之有「禽」也。古者搜苗猕狩，通谓之田，主于除害也。禽入我田，蹂践禾稼，利在于执，不可纵舍。若快心纵舍，游田无度，烈山泽而焚之，则兽不得安其居，人不得食其利矣。传曰：「利人土地货宝者，谓之贪兵。兵贪者败。不得已而起者，谓之应兵。应兵者胜。」蛮夷滑夏，寇贼奸宄，不得已而用师，则「执田禽」之义也，故曰：「吉，无咎。」帝王之师，所以无敌于天下者，用此道也。夫说者沿袭讹诬，以执言为命辞，陋矣！夫动民以行不以法，应天以实不以名。克宽克仁，彰信兆民，东征西怨，南征北怨，岂区区执言而与之较哉？故彖言「大人吉，无咎」，而二、五之爻辞皆表而出之，不以为赘者，所以显微而阐幽，不得不然尔。既曰「吉」，又曰「无咎」，何也？曰：「无咎者，善补过也。」夫以九二在下，而有震主之威，六五居尊，而行天下之险，宜其有咎矣。以其刚中而应，行险而顺，故得无咎，岂非善补过之谓乎？故曰：「长子帅师，弟子舆尸，贞凶。」长子，「震」也。「弟子」，「坎」、「艮」也。应于九二，既有「长子帅师」之象；乘乎三四，复有「弟子舆尸」之忧。夫柔顺者，五之所以为「贞」也。委任九二而责其成，不从中御，斯为善矣。然柔而无断，则任不专一，二三其责，将有「舆尸」之凶矣。故子曰：「长子帅师，以中行也；弟子舆尸，使不当也。」夫长子也者，岂直谓其年长也哉？以其刚中而行健，当主帅之事，斯谓之长子矣，谓其有长人之材故也。苟或任所不当，十羊九牧，无所适从，欲无凶，得乎？或曰：卦以一阳为五阴之主，而六五谓之「大人」，何也？曰：五者，尊也；六者，柔也。以柔居尊，而九二为之应，吾能左右而使之，所谓能以众者也。坤为顺，震为动，坎为险，六五体坤而应乎正，去险难而就平地，所谓行险而顺者也。谓之「大人」，不亦宜乎？世言用武之君，往往皆以勇略冠世，然后能之。此浅俗之论，非智识之谈也。老子曰：「强大处下，柔弱处上。」夫惟不争，故天下莫能与之争。然则师之大人，以六居五，责成九二，以收拨乱之功，此韩信之所以为善将兵，而高帝之所以为善将将也。臧宫、马武之徒所以鸣剑抵掌，而光武之所以闭关而谢质也。文帝劳亚夫之军，军门都尉曰：「军中但闻将军之令，不闻天子之诏。」自非文帝，有不能堪。以是知六五之为难能也。上六：大君有命，开国承家，小人勿用。象曰：「大君有命」，以正功也。「小人勿用」，必乱邦也。上六，「坤」也，以阴居柔，而在一卦之上，下无其应，而乘乎六五之「坤」，故曰：「大君有命，开国承家」。五居天位，故有「君命」之象。「坤」为上，为众，为国邑，故有「开国成家」之象。方师之初，一阳在下而为之主，五阴莫不顺听者，「行师」之义也。及夫「开国承家」，而听九二之制，则无君矣。故必「大君有命」，而后可以正其功。上居一卦之终，班师振旅，论功行赏之时也。故曰「小人勿用」。大者开国而为公侯，小者承家而为卿大夫。而小人之有功，赏之而勿用，此为国久长之计也。或曰：「谓之承家，则必继世而后可乎？」非此之谓也。封之土而命之氏，使其子孙得以承袭，是之谓承家也。甚哉！小人之不可用也。譬之犹虎狼蝮蝎然，欲其不为民害，不可得也。圣人知其有功不可不赏也，故戒以「勿用」而已。或曰：小人之不可一日用也，而使之有功，何哉？曰：军旅之事，使智使勇，使愚、使贪，古之道也，岂暇问君子小人哉？惟开国承家，然后得而审理之。武王克商，大封于庙，其诗曰「赉」，说者谓有周赉子也，言所以锡善人也。孔子曰：「周有大赉，善人是富。八百诸侯，三千虎士。」夫岂皆善人哉？其处之必有道矣。或曰：「功同赏异，则必悍然而不平，圣人将何以处之？」曰：象至不仁，封之有庳，天子使吏治其国，而纳其贡赋焉，何忧其悍而纵其为暴也？光武惩高帝之事，不任功臣，得其道矣。或曰：师之诸爻，孰为君子？孰为小人？曰：九二、六四、上六，君子也。初六、六三，小人也。以九居二，德浮于位者也。六四、上六，德称其位者也。初六、六三，则小人而乘君子之器也。初与三为坎，坎为小人故也。是以诸爻无咎，而初与三皆凶也。子曰：「大君有命，以正功也。小人勿用，必乱邦也。」夫大君者，以公天下为心者也。论功行赏，蔑不正矣。晋之王浑、王濬，隋之韩擒虎、贺若弼，所以争功而不决者，二主之不君，从可知矣。若汉高帝有片言之喻，孰敢不听乎哉？序卦曰：众必有所比，故受之以比。比者，比也。比也者，亲附之谓也。比之阙视师，比之象也。夫师、比，五阴而一阳，刚中而应，行险而顺，均也。其所以为师为比者，二五之位尊卑之不同耳。其在于二，人臣之位也，可以行师而非立国之道也。其在于五，人君之位也，可以立国而非行师之义也。是故九二者，众之所奉以为正也；九五者，众之所戴以为君也。书曰：「万夫之长，可以观政。」九二之谓也。又曰：「众非元后何戴？」九五之谓也。此「师」、「比」之所以异也。比：吉。原筮，元永贞，无咎。不宁方来，后夫凶。彖曰：比，辅也，下顺从也。「原筮，元永贞，无咎」，以刚中也。「不宁方来」，上下应也。「后夫凶」，其道穷也。下坤上「坎」。成卦曰「比」者，「坤」为众，为顺，艮为止，「坎」为险。众而止于险，「比」之势也；顺而止乎险，「比」之情也。「坎」、「坤」之中有「震」象焉，所以为「师」也；「坤」、「坎」之中有「艮」象焉，所以为「比」也。或曰：子于师之左次，田之有禽，皆以「艮」象言之矣。于此乃曰坎、坤有「震」而为师，坤、坎有艮而为比，何其相戾也？曰：易有四象，谓正体也。覆而取之，又四象也。一卦之彖，据正体而言之，及其在爻，至四而止矣。苟不覆之，则五、上二爻，将无所取；而三、四二爻，亦无以明反复变化之义矣。故曰：「杂物撰得，辩是与非，则非其中爻不傋」，此之谓也。或曰：然则坤、坎为师，坎、坤为比，亦有其义乎？曰：「坎」也者，法度之所自出也。法度在下，而上顺从之，所以为「师」也；法度在上，而下顺从之，所以为「比」也。比：吉，原筮，元永贞。何谓也？曰：九五之谓也。受天下之比，如九五之正，可谓「吉」矣。天下之人，得其所「比」，如九三者，可谓「无咎」矣。故曰：「比，吉也。」「比」，辅也，下顺从也。「辅」，当为「富」，传写误耳。「顺从」云者，自四以下，皆「坤」象也。筮之为言，决疑之谓也。以阴比阳，以贱比贵，得其所以比则「吉」，失其所比则「凶」。吉凶之间，祸福之际，明者据之，取占筮之义也。原者，再也。犹原蚕、原庙之义也。元，始也。永，终也。贞，正也。筮其所以始终皆正，如九五者，可以无咎矣。夫以五阴而比一阳，其从之也，岂俟占而后决哉？然而筮之至于再，何也？曰：去就之义大矣。贤者有所不知，而况于众人乎？卦为二五、初四为吉，至于三上两爻，有「匪人无首」之凶，不知「原筮」之故也。六三非阳也，而居于刚，自以为阳，而求配于上六，又介乎二四之间。二四舍三而此五，上六舍五而比二，吉凶之来，自取之也，可不审乎？九五体阳而居刚，六二、六四、上六体阴而居柔，如是而比，斯谓之「元永贞」者矣。故曰：原筮，元永贞，无咎，以刚中也。不宁方来，谓初六也。九五在上，六二在下，当比之时，而有不当其位者，非背叛之臣，即裔夷之君长也。初六一爻，最为僻远，以阴居刚，不当其位，其四夷之国，不宁之方乎？初近于二，配于四，二四既得所比，初之从五，不占而决矣。故曰：「不宁方来，上下应也」。后夫凶，谓上六也。夫也者，妻之所比也。君也者，臣之所比也。当比之时，九五中正，于臣民为君，于妻妾为夫。自四以下，莫不顺之。所谓阳唱而阴和，男行而女随也。上六独乘于五，是后其夫也，其凶宜矣。孟子曰：「未有义而后其君者也」。或曰：三上配也，岂得反谓五为夫？曰：五阴一阳，阳居中正，天下一家之象也。天无二日，民无二王，上不比五而比三，是谓比之无首，比他人而后其夫也。上之所以比三者，为其居之可配，而不知其德之非夫，失「原筮」之道也。故曰：「后夫凶，其道穷也。」或曰：蒙之彖曰：初筮告，再三渎。渎则不告。明筮贵初而恶夫渎也。今比之筮而贵乎再，是故将渎之也欤？曰：夫言各有当也。书曰：「卜不习吉。」初筮之谓也。又曰：「一习吉。」原筮之谓也。蒙者之于「师」，亟问而弗志于心，其弗告之宜矣。臣之从君，妇之从夫，不可以苟合，苟合则离。思其始而图其终，所以为久长之道也，何恶于原筮也哉？象曰：地上有水，「比」。先王以建万国，亲诸侯。「地」者，「坤」也；「水」者，「坎」也。天下之水，未有不附于地者。「地中有水」，水之聚也；「地上有水」，水之散也。水聚则为泽，及其散也，或为江河，或为沟渎，而莫不比于地。民聚则为师，及其散也，或为方伯之国，或为子男之邦，而莫不比于王。此先王所以「建万国，亲诸侯」也。杂卦曰：「比乐师忧。」「坎」之一阳，为五阴之主，在「师」为忧，在「比」为乐，何也？曰：「师」、「比」以二五为主，「师」之二五不当其位，「比」之二五皆得其正故也。柔上而刚下，上下之所同忧也。阳尊而阴卑，尊卑之所同乐也。夫兴师动众，以毒天下，拯之涂炭之中，而措之衽席之上，岂不始于忧勤，而终于佚乐也哉？天下有王，生民有归，于斯时也，可谓乐矣。是故「比」之诸爻，皆有佚乐之象。六二自内而吉，六四自外而亦吉，初六自他而亦吉，九五不诫而亦吉，惟六三、上六失其所比，有「匪人无首」之象也。当比之时，九五在上，顺之者吉，逆之者凶；顺之者安荣，逆之者危辱。自非反道背德之人，谁肯避吉而就凶，舍安荣而取危辱哉？此「比」之所以为乐也。故曰：「比者，比也。」其他爻则以上下相比明其义焉。初六：有孚比之，无咎。有孚盈缶，终来有他，吉。象曰：比之初六，「有他吉」也。初六，「坤」也，以阴居刚，而在一卦之下，上无其应，而承乎六二，二亦「坤」也，故曰：「有孚比之，无咎。」「坎」为有孚，谓九五也。以震而居坎中，群阴之所孚也。二应在五而比于初，四应在初而比于五，故初因二与四而得其所比焉，所谓「因不失其亲」者也。所以然者，初体「坤」，「坤」为顺，凡「比」之道，元永皆正，然后无咎。今初六最远于五，不当其位，见五之有孚，而远来比之，曷为无咎乎哉？孟子曰：「天无二日，民无二王。」诗云：「自西自东，自南自北，无思不服。」九五之谓也。初六避远，因二与四而得所比，又何咎之有哉？故曰：「有孚盈缶，终来有他吉。」「坎」为「缶」，九五，「坎」中之阳，流而不盈者也。自四以下，皆「坤」象焉。以土制水，则其缶盈矣。「盈缶」也者，言其充实也。有诸中必形诸外，诚于此必著于彼。九五之孚，仅盈一缶，而有自他来比之者，初六是也。初为无咎，而五为吉矣。或曰：九五在上，无所不孚，而以盈缶言之，何也？曰：江出岷山，其源滥觞，极其所至，放乎四海。盈缶之孚，足以充塞乎天地之间矣。为人上者，患诚信之不充耳。苟能充之，何忧天下之不王，四夷之不服哉？子曰：「比之初六，有他吉也。」夫爻既言之矣，夫子又申言之，不几于赘乎？曰：圣人之言简而明，质而尽，学者顾未之思耳。今言易之家，皆于别爻求他吉之义，然后知圣人有味其言之也。盖曰比之他吉，不在别爻，即初六是也。岂不简而明、质而尽也哉？六二：比之自内，贞吉。象曰：「比之自内」，不自失也。六二，「坤」也。以阴居柔而在下卦之中，应乎九五之「震」，而承乎六三。三，「坤」「艮」也，故曰：「比之自内。」下卦为内，上卦为外，九五在上，六二自内而比之，故曰：「贞吉」。当比之时，二五中正，自内比之，可谓元永贞正，吉而无咎者矣。子曰：「比之自内，不自失也。」夫以阴柔为体乎「坤」，不忧其不顺于五，而忧其自失于三也。能保其正，不自失于匪人，斯为吉矣。六三：比之匪人。象曰：「比之匪人」，不亦伤乎？六三上体为「艮」，下体为「坤」，以阴居刚而在下卦之上，上无其应，而介于二、四，二爻皆「坤」，而三又「坎」也。故曰：「比之匪人。」「匪人」者，非所比而比焉者也。二以其中，四以其近，皆获「比」于五矣。独上六后夫，而与三为背，谓之「匪人」，不亦宜乎？阳为贵，阴为贱。贱者，比人者也。贵者，比于人者也。阳为贤，阴为不肖。不肖者，比人者也。贤者，比于人者也。是故「比」五阴而一阳。五阴之爻皆言比之者，比人者也。一阳之爻独言显「比」者，比于人者也。比于人者，治人，比人者，治于人。今六三、上六二爻皆阴，莫能相尚。三虽居刚，而上又一卦之上；三虽体「艮」，而上乂体「坎」，是故皆有「比之」之辞，明其才德俱茂，不能以自立，相比而莫适为尊也。子曰：比之匪人，不亦伤乎？已不能以自立，所比者又非其人，祸至无日矣，不亦可伤哉？在汉建武、隗嚣、公孙述、荀若、窦融者，初六当之矣。六四：外比之，贞吉。象曰：「外比」于贤，以从上也。六四上体为「坎」，下体为「坤」，以险居柔，而在上卦之下，下无其应，而承乎九五之震，故曰：「外比之，贞吉。」六二为内比，六四为外比，明矣。夫以六四之「坤」而承乎九五之「震」，其比之也固也，为其有「坎」象焉。「坎」性下流，是以戒之，守其正，然后吉也。子曰：「外比于贤，以从上也。」上者，对下之称。四之配在初而乘乎三，二爻皆阴也。阳为贤，阴为不肖，舍不肖而比贤，四之所以为「贞吉」者欤！九五：显比，王用三驱，失前禽，邑人不诫，吉。象曰：「显比」之吉，位正中也。舍逆取顺，「失前禽」也。「邑人不诫」，上使中也。九五，「震」也。以阳居刚而在上卦之中，应乎六二，而为五阴之所宗，故曰「显比」。阳为明，阴为晦。「震」，东方也，日之旦也。以大中至正之道，显然受天下之比也。诚意以待之，虚心以纳之，来者不拒，去者不追，较然不欺其心，俯仰而无愧怍，此之谓「显比」。古之圣人所以得天下者，皆是道也。故曰：「王用三驱，失前禽，邑人不诫，吉。」「王」谓五也，五体「震」，震为马，下应乎二，所历三爻，故有「王用三驱」之象。「禽」，谓三也，三体「艮」，「艮」为黔喙之属。三自内比，四自外比，而三独不顺，比之匪人，故有「失前禽」之象。「邑」谓六二也，二体「坤」，「坤」为国邑，柔顺中正而与五为应，故有「邑人不诫」之象。「王用三驱」，即礼所谓天子不合围是也。三面而驱，阙其一面，顺而来者取之，逆而去者舍之，古之道也。夫三面而驱，禽之逸者固多矣。圣人以为外物，任其去来而不强取之也。故曰：「子钓而不纲，弋不射宿。」成汤之祝曰：「欲左者左，欲右者右，不用命者，入吾网。」圣人之仁，盖如此也。或曰：汤以一面而王用三驱，何也？曰：三驱，礼也。汤之一面，代虐以宽，矫枉过正，非常道也。原其设心则同矣。若夫邑人，则吾之所与同其休戚者也。方其未附也，去来逆顺有所不可知。及其附也，则巩如磐石，固如胶漆，亲如父子，护如头目，又何诫之有哉？是以大有之盛，至于易而无备；泰之盛，至于不戒以孚，然后为至也。然则圣人不取必于前禽，而取必于邑人；不取必于邑人，而取必于吾身。使吾德可比，则邑人不诫。邑人不诫，则前禽安往哉？以此显比，可谓吉矣。子曰：显比之吉，位正中也。舍逆取顺，失前禽也。邑人不诫，上使中也。书曰：「尔身克正，罔敢不正。民心罔中，为尔之中。」上使中之义也。夫六二虽居中履正，苟无九五之君，将不能保其正矣。上之所使，不其然欤？郑康成曰：「舍而去之不射，走而往者顺而射。」王弼亦曰：禽走来趋己则舍之，背己而走，则取之。既违经旨，且非事情。又曰：可以为上之使，非为上之道。失之远矣。王氏明象曰：古者田猎，驱禽兽于所聚之野而射之，三驱而止，未详所出，亦恐不近人情。上六，比之无首，凶。象曰：「比之无首」，无所终也。上六，坎也，以阴居柔，而在一卦之上，下无其应，而乘乎九五之震，故曰：「比之无首」。上六以柔乘刚，而不顺九五，而反与六三为比者也。小人群居，莫适为首，故曰「凶」。两贵不能以相事，两贱不能以相使，「比」而「无首」，「凶」不亦宜乎？「乾」之上九，「无首」而「吉」；比之上六，「无首」而「凶」。学者观之，思过半矣。子曰：比之无首，无所终也。夫以六三「比之匪人」，固可以为凶矣，犹然不系以凶咎之辞者，其逆顺未可知也。使其幡然从天下之所归往，孰能御之哉？至于上六，卦之终也，而卒于「无首」，其凶成矣。此所谓初辞拟之，卒成之终者欤？曰：上之于三，既非其配，而切近于九五，乌知其不从五而反比于三与？曰：为其后之故也。方比之时，一阳在上，六二自内而比之，六四自外而比之，初六自远而比之。唯六三、上六各居一卦之上，皆有雄长之心，是以相与为比而至于后。夫所谓天下后服者先亡矣，而况于近而不相得乎？所以然者，九五震也，上六坎也，六三艮也，自以皆得乾之一体，是以不汲汲而从五也。或曰：「六四之坎也，而比之，何哉？」曰：四以阴居柔，而在上卦之终，体乎坤而成乎震，其比之也，不亦宜乎？非三、上之比也。周易经传集解卷四。",-1)])])}const _=t(r,[["render",c]]);export{m as __pageData,_ as default};
